Fixpoint frames_eqb (a b : list (expr * Z * Z)) : bool :=
  match a, b with
  | [], [] => true
  | x :: a', y :: b' => (expr_eqb (fst (fst x)) (fst (fst y)) && Z.eqb (snd (fst x)) (snd (fst y)) && Z.eqb (snd x) (snd y) && frames_eqb a' b')%bool
  | _, _ => false
