Lemma keepc_regs_sem : forall E BL FL LB FF scr c r a, env_agree NF E0 E -> rng_facts LB FF ->
  incl (CH2.den E BL ++ LBrest) LB -> incl (denF E FL ++ FFrest) FF ->
  c <= 0 -> 0 <= scr -> - SCR <= c - scr -> 0 <= a < 2 ^ 64 ->
